vec3 palette( float t ){
     vec3 a = vec3((sin(iTime*1.32456)),cos(iTime*0.76354),sin(iTime));
     vec3 b = vec3(.75,.25,.65);
     vec3 c = vec3(1.,1.,1.);
     vec3 d = vec3(0.263,0.416,0.557);
     return a+b*cos( 6.28318*(c*t+d) );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy*2.-1.;

    uv.x*=iResolution.x/iResolution.y;

    vec2 uv0=uv;

    vec3 fcol=vec3(0.);

    float f=25.;//change f to increase number of iterations and thus detail

    for (float i =1.0; i<f; i++){

        uv.x+=sin(uv.y*i+iTime)/i+uv.y;

        uv.y+=cos(uv.x*i+iTime)/i-uv.x;

        float d =length(uv)*exp(-length(uv));

        vec3 col = sin(palette(length(uv)+iTime*0.4));

        //col.r=step(col.r,0.05);
        //col.g=step(col.g,0.05);
        //col.b=step(col.b,0.05);

        fcol+=col*d/(f-i);
    }

    fragColor = vec4(fcol,1.0);
}
